declare module 'claude-code' {
  interface PluginState {
    'leo-mods': {
      costUsd: Usd
      contextPercent: Percent
      limits: Limit[]
      runningAgents: number
      activeMs: number
      cacheAt: number | null
      cacheTtlMs: number | null
      cacheLeftMs: number | null
      nowMs: number
      mascotMood: Mood
      mascotFrame: number
    }
  }
}
